// Fully authored Ballpark 2026 content bank.
// Generated once from the editorial reset workspace so runtime no longer rebuilds prompts from theme families.

const PLAYER_AGENT_ROLES = Object.freeze([
  "Casual Morning Player",
  "Math-Averse Player",
  "Skeptical Trivia Player",
  "Competitive Player",
  "Mobile UX Player",
  "Family Couch Player",
  "Social Sharer",
  "Editorial Calendar Player",
  "NYT Word Game Player",
  "Daily Word Search Player",
  "Connections Pattern Player",
  "Fermi Estimator"
]);
const SCORE_KEYS = Object.freeze(["firstGuessFairness","calibrationFun","revealSatisfaction","copyClarity","freshness"]);

function source(title, url, publisher) {
  return { title, url, publisher, accessedDate: '2026-05-23' };
}

