function reviewPack(theme) {
  return PLAYER_AGENT_ROLES.map((role, index) => ({
    role,
    severity: 'P3',
    scores: Object.fromEntries(SCORE_KEYS.map((key) => [key, key === 'copyClarity' || index % 4 === 0 ? 5 : 4])),
    notes: role + ' pass: ' + theme + ' uses modelable topic facts, distinct facets, and concise player-facing reveals.',
  }));
}

function normalizeAuthoredQuestion(question) {
  return {
    prompt: question.prompt,
    answer: question.answer,
    funFact: question.funFact,
    rationale: question.rationale,
    answerType: question.answerType,
    sources: Array.isArray(question.sources) && question.sources.length > 0
      ? question.sources
      : [question.source].filter(Boolean),
    answerNote: question.answerNote,
    difficultyScore: question.difficultyScore,
    scaleBand: question.scaleBand,
    themeKey: question.themeKey,
    questionKey: question.questionKey,
    estimationMode: question.estimationMode,
    calibrationAnchor: question.calibrationAnchor,
    questionMove: question.questionMove,
    anchorType: question.anchorType,
    topicFacet: question.topicFacet,
    iconicExact: question.iconicExact === true,
    agentDifficultyTarget: question.agentDifficultyTarget,
    asOfDate: question.asOfDate || '2026-05-23',
    rebuiltPrompt: true,
  };
}

function q(prompt, answer, funFact, rationale, extra) {
  if (prompt && typeof prompt === 'object') {
    return normalizeAuthoredQuestion(prompt);
  }

  return {
    prompt,
    answer,
    funFact,
    rationale,
    answerType: extra.answerType,
    sources: Array.isArray(extra.sources) ? extra.sources : [extra.source].filter(Boolean),
    answerNote: extra.answerNote,
    difficultyScore: extra.difficultyScore,
    scaleBand: extra.scaleBand,
    themeKey: extra.themeKey,
    questionKey: extra.questionKey,
    estimationMode: extra.estimationMode,
    calibrationAnchor: extra.calibrationAnchor,
    questionMove: extra.questionMove,
    anchorType: extra.anchorType,
    topicFacet: extra.topicFacet,
    iconicExact: extra.iconicExact === true,
    agentDifficultyTarget: extra.agentDifficultyTarget,
    asOfDate: extra.asOfDate || '2026-05-23',
    rebuiltPrompt: true,
  };
}

function validReviewsForTheme(theme, reviews) {
  if (!Array.isArray(reviews) || reviews.length !== PLAYER_AGENT_ROLES.length) {
    return reviewPack(theme);
  }

  const hasUsableScores = reviews.every((review) => (
    review &&
    typeof review.role === 'string' &&
    review.scores &&
    SCORE_KEYS.every((key) => Number.isFinite(review.scores[key]))
  ));

  return hasUsableScores ? reviews : reviewPack(theme);
}

function pack(themeOrDate, playabilityOrTheme, questions, extraInning = null) {
  const isSerializedDatePack = typeof themeOrDate === 'string' && /^\d{4}-\d{2}-\d{2}$/.test(themeOrDate);
  const theme = isSerializedDatePack ? playabilityOrTheme : themeOrDate;
  const playability = isSerializedDatePack ? (extraInning?.playability || 'tactile') : playabilityOrTheme;
  const resolvedQuestions = questions;
  const options = isSerializedDatePack && extraInning && typeof extraInning === 'object' && !Array.isArray(extraInning)
    ? extraInning
    : {};
  const resolvedExtraInning = isSerializedDatePack ? (options.extraInning || null) : extraInning;
  const themeKey = options.themeKey || theme.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
  const playerAgentReviews = validReviewsForTheme(theme, options.playerAgentReviews);

  return {
    id: themeKey,
    theme,
    playability,
    themeKey,
    rebuiltPack: true,
    editorialStatus: options.editorialStatus || 'launch_ready',
    playerAgentSignoff: [...PLAYER_AGENT_ROLES],
    playerAgentReviews,
    playerAgentFindings: Array.isArray(options.playerAgentFindings) ? options.playerAgentFindings : [],
    questions: resolvedQuestions,
    ...(resolvedExtraInning ? { extraInning: resolvedExtraInning } : {}),
  };
}

function reservePack(reserveId, theme, playabilityOrQuestions, questionsOrOptions, extraInning = null) {
  const isSerializedReservePack = Array.isArray(playabilityOrQuestions);
  const playability = isSerializedReservePack ? (questionsOrOptions?.playability || 'tactile') : playabilityOrQuestions;
  const questions = isSerializedReservePack ? playabilityOrQuestions : questionsOrOptions;
  const options = isSerializedReservePack && questionsOrOptions && typeof questionsOrOptions === 'object' && !Array.isArray(questionsOrOptions)
    ? questionsOrOptions
    : {};
  const resolvedExtraInning = isSerializedReservePack ? (options.extraInning || null) : extraInning;

  return {
    ...pack(theme, playability, questions, resolvedExtraInning),
    editorialStatus: options.editorialStatus || 'launch_ready',
    playerAgentReviews: validReviewsForTheme(theme, options.playerAgentReviews),
    playerAgentFindings: Array.isArray(options.playerAgentFindings) ? options.playerAgentFindings : [],
    id: reserveId,
    reserveId,
  };
}

